package com.costeo3d.infrastructure.persistence.dao;

import java.util.List;
import java.util.Optional;

import com.costeo3d.domain.model.Spool;

public interface SpoolDao {

    // Returns a new Spool instance with the ID generated by MySQL.
    Spool insert(Spool spool);

    Optional<Spool> findById(int id);

    // Includes active and inactive spools.
    List<Spool> findAll();

    // Returns false if no spool exists with the given ID.
    boolean update(Spool spool);
}
